import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
rows=[
('sn_tower/__init__.py',70,'Lazy export facade for toy S0–S6, realizations, applications and verification owners. Governing-standard names add no executable proof or layer enforcement.'),
('sn_tower/sn_core.py',194,'Explicit algebraic-shadow toy models. Empty-set inertia, singleton supply, unordered-set symmetry and identity/product section-retraction follow definitions; do not derive external marks or nonexistence. Cost2 is a checked supplied constant, not minimization proof. Complete-edge count trusts distinct vertex inputs; duplicate two-vertex input can produce a self-loop while satisfying count. Triangle orientation verifier checks only tuple length3 and accepts all-equal vertices. Continuation copies set and compares equality, so endogenous inertia is stipulated operation. Descent status depends only on supplied delta, not a map or obstruction.'),
('sn_tower/sn_verification.py',146,'Alternation monitor detects repeated exact state strings without increasing progress, bounded by supplied depth only; no AST polarity or quantifier evaluation and history can grow. DDA claims14-tuple but has12fields, checks budget>=cost and carrier delta only; negative budgets/costs and other state transitions unvalidated. Kleene tables implement the three values but map unexpected values to unknown. RGB channel executes supplied callback with bool coercion, stores IDs without source/proof binding, does not revoke green on later false, and produces no signature despite signed-receipt prose. Genesis promotion method always raises, a real local fence.'),
('sn_tower/sn_realizations.py',235,'Mixture of genuine elementary operations and labels: finite quantifier any/all, decreasing string reduction, product left inverse, edge enumeration, nested finite sets and count formulas. Simplex self-loop dictionary overwrites instead of cancelling. Dagger removes/appends a suffix and endpoint-only check ignores label involution failure. RGB ignores claim body and keeps green after false. Hodge is dimension addition only, Hashimoto just doubles edge count, dialect projection is names, and autopoietic audit always AUDIT_PASS with declared rule count. None establishes adjunction naturality/triangle laws, orthogonal harmonic splitting, spectral theory, authenticated receipts or generic mathematical realizations.'),
('sn_tower/sn_applications.py',106,'Finite relational join on exact shared department has ordinary set semantics. Session state ignores payload and permits repeated sends before one receive despite single-use description; it does block sends after close and receive before send. Downstream fences are explicit callable checks, not constructor invariants. Equilateral2D Gram determinant3s²/4 and trace2s provide positivity for positive finite scale only; float overflow/NaN have numeric limits. Curvature subtracts supplied angle sum from2pi and uses tolerance; no incidence, dimension or geometric angle derivation.'),
('synthesis/__init__.py',11,'Exports ModuleDag/Node/Status and RetractionContext; no scheduler implementation or synthesis authority beyond imported owners.'),
('synthesis/module_dag.py',66,'Mutable in-memory dependency scheduler marks first pending node ready when all dependency names frozen. No cycle/missing-dependency checks, duplicate add replaces nodes, dependencies remain mutable aliases. freeze accepts arbitrary code from any state without proof, tests or digest; frozen is workflow status only. Nonempty all-frozen check is useful but not verified correctness, and authority strings are not enforced.'),
('synthesis/retraction_context.py',54,'Prompt builder requires truthy previous_code and failing_diff for attempts>=2, preserving repair context text. Does not validate attempt type/range, provenance of failed verification, relationship of diff to source or actual retraction semantics; authority is an unenforced field. No provider or code execution, prompt is data.'),
('survivor_dedup.py',37,'Drops only separator_operation_map survivors whose application to one query equals a non-map survivor result. This is one-query observational equality, not operator equivalence or complete survivor quotient. Other duplicates remain, unhashable outputs fail, callbacks may execute repeatedly and their effects are caller-owned. Safe wrapper catches exceptions into DomainError; previously reviewed shared result owner supplies compatible API.')]
for p,l,s in rows:a.record('pfp/domain/'+p,1,l,s)
n=a.read('_notes.json');n['controls'].extend(a.read('_sn_probes.json')['controls'])
def ev(p,*rs):
 p='pfp/domain/sn_tower/'+p;return {'path':p,'sha256':a.row(p)['sha256'],'lines':[list(x) for x in rs]}
for number,title,statement,es,ids in [
(58,'Toy RGB channels retain green after failed re-verification','Both RGB implementations add green on true but never discard it on false. Re-verifying the same ID true then false leaves green present while the stored blue verdict is false. Callbacks are bool-coerced, so the string false is also accepted. Claims and proof bodies are not bound or signed by these sets.',[ev('sn_realizations.py',(137,161)),ev('sn_verification.py',(116,146))],[74]),
(59,'Simplex shadow boundary fails on admitted degenerate endpoints','Simplex1 accepts identical endpoints then constructs {v:1,u:-1}; dictionary overwrite yields coefficient minus1 rather than cancelling v-u to zero. The S5 triangle orientation check separately accepts three identical vertices because it only checks boundary tuple length. Distinctness is not enforced in these constructors/checkers.',[ev('sn_realizations.py',(13,26)),ev('sn_core.py',(111,132))],[75]),
(60,'Dagger checker ignores arrow-label failure of involution','For label f^dagger^dagger, applying dagger twice produces f, while verify_double_dagger returns true because it compares endpoints only. Thus the full dataclass arrow does not satisfy the claimed dagger involution on unrestricted admitted labels.',[ev('sn_realizations.py',(102,118))],[76]),
(61,'Single-use session permits repeated sends','SessionChannel accepts two sends in succession before one receive. send only checks is_closed, ignores current SENT state and drops payload. Its state machine enforces closure after receive but not the advertised single-use send protocol.',[ev('sn_applications.py',(26,45))],[77])]:n['findings'].append({'id':'PFPDOMAIN-F'+str(number).zfill(3),'title':title,'statement':statement,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':['PFPDOMAIN-C'+str(i).zfill(3) for i in ids],'status':'confirmed_bounded_source_and_probe','limits':'Toy domain owners only. No external session, host authorization, provider or retained program executed.'})
a.write('_notes.json',n);a.report()
